@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int CurrentStep { get; set; } = 1;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private string? _emailError;
    private bool _isValidating;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    // Submission
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    private string StepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            _errorMessage = null;
        }
    }

    private void PreviousStep()
    {
        if (CurrentStep > 1)
        {
            CurrentStep--;
            _errorMessage = null;
        }
    }

    // Step 1 validation
    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email.Trim());
            if (!valid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
            CurrentStep = 2;
        }
        finally
        {
            _isValidating = false;
        }
    }

    // Step 2 validation
    private void NextFromWorkHistory()
    {
        _errorMessage = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for all positions.";
                return;
            }
        }
        CurrentStep = 3;
    }

    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    // Step 3 validation
    private void NextFromReferences()
    {
        _errorMessage = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        CurrentStep = 4;
    }

    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);

    // Step 4 validation
    private void NextFromCoverLetter()
    {
        _errorMessage = null;
        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }
        CurrentStep = 5;
    }

    // Submit
    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;
        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim()),
                new WorkHistory(_workEntries.Select(e => new WorkEntry(
                    e.Company.Trim(), e.Title.Trim(), e.StartDate,
                    e.IsCurrent ? null : e.EndDate, e.Description?.Trim() ?? "")).ToList()),
                _references.Select(r => new Reference(
                    r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())).ToList(),
                _coverLetter.Trim()
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch
        {
            _errorMessage = "An error occurred while submitting. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    // Mutable models for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

.step-indicator .step-item {
    flex: 1;
    position: relative;
    z-index: 1;
    cursor: default;
}

.step-indicator .step-item.completed {
    cursor: pointer;
}

.step-progress-track {
    position: absolute;
    top: 16px;
    left: 10%;
    right: 10%;
    height: 4px;
    background-color: #dee2e6;
    z-index: 0;
    border-radius: 2px;
}

.step-progress-fill {
    height: 100%;
    background-color: #198754;
