@using sv_270d905c47234e0590f39128adcf034b.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="step-indicator mb-4">
        <div class="d-flex justify-content-between position-relative">
            <div class="step-progress-track">
                <div class="step-progress-fill" style="width: @($"{(CurrentStep - 1) * 25}%")"></div>
            </div>
            @for (int i = 1; i <= StepNames.Length; i++)
            {
                var step = i;
                <div class="step-item text-center @StepClass(step)" @onclick="() => GoToStep(step)">
                    <div class="step-circle">
                        @if (step < CurrentStep)
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            <span>@step</span>
                        }
                    </div>
                    <div class="step-label small mt-1">@StepNames[step - 1]</div>
                </div>
            }
        </div>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger alert-dismissible fade show" role="alert">
            @_errorMessage
            <button type="button" class="btn-close" @onclick="() => _errorMessage = null"></button>
        </div>
    }

    @if (_submitted)
    {
        @* ───── Confirmation ───── *@
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 3rem; color: #198754;">&#10003;</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">We'll review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        @* ───── Step 1: Personal Info ───── *@
        @if (CurrentStep == 1)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Personal Information</h4>
                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="_fullName" @bind:event="oninput" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control @(_emailError != null ? "is-invalid" : "")"
                               @bind="_email" @bind:event="oninput" />
                        @if (_emailError != null)
                        {
                            <div class="invalid-feedback">@_emailError</div>
                        }
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" @bind:event="oninput" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea class="form-control" rows="2" @bind="_address" @bind:event="oninput"></textarea>
                    </div>
                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Next &raquo;
                        </button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 2: Work History ───── *@
        @if (CurrentStep == 2)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Work History</h4>
                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var idx = i;
                        var entry = _workEntries[idx];
                        <div class="border rounded p-3 mb-3 bg-light">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Position @(idx + 1)</h6>
                                @if (_workEntries.Count > 1)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                                }
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Company <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="entry.Company" @bind:event="oninput" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="entry.Title" @bind:event="oninput" />
                                </div>
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-4">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" @bind="entry.StartDate" />
                                </div>
                                <div class="col-md-4">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                                </div>
                                <div class="col-md-4 d-flex align-items-end pb-1">
                                    <div class="form-check">
                                        <input class="form-check-input" type="checkbox" @bind="entry.IsCurrent"
                                               id="@($"current-{idx}")" />
                                        <label class="form-check-label" for="@($"current-{idx}")">Currently working here</label>
                                    </div>
                                </div>
                            </div>
                            <div class="mb-0">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                            </div>
                        </div>
                    }
                    <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                        + Add Another Position
                    </button>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next &raquo;</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 3: References ───── *@
        @if (CurrentStep == 3)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">References</h4>
                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var idx = i;
                        var reference = _references[idx];
                        <div class="border rounded p-3 mb-3 bg-light">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Reference @(idx + 1)</h6>
                                @if (_references.Count > 2)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                                }
                            </div>
                            <div class="row mb-2">
                                <div class="col-md-6">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="reference.Name" @bind:event="oninput" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input type="text" class="form-control" @bind="reference.Relationship" @bind:event="oninput" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-6">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" @bind="reference.Email" @bind:event="oninput" />
                                </div>
                                <div class="col-md-6">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" @bind="reference.Phone" @bind:event="oninput" />
                                </div>
                            </div>
                        </div>
                    }
                    @if (_references.Count < 3)
                    {
                        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                            + Add Reference
                        </button>
                    }
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromReferences">Next &raquo;</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 4: Cover Letter ───── *@
        @if (CurrentStep == 4)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Cover Letter</h4>
                    <div class="mb-2">
                        <textarea class="form-control" rows="10" maxlength="2000"
                                  @bind="_coverLetter" @bind:event="oninput"
                                  placeholder="Tell us why you're a great fit for this position..."></textarea>
                    </div>
                    <div class="text-muted small mb-3 text-end">
                        @(_coverLetter?.Length ?? 0) / 2000 characters
                    </div>
                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                        <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next &raquo;</button>
                    </div>
                </div>
            </div>
        }

        @* ───── Step 5: Review & Submit ───── *@
        @if (CurrentStep == 5)
        {
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Personal Information</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Work History</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="border-start border-3 border-primary ps-3 mb-3">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <small class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </small>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">References</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                    </div>
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> &mdash; @r.Relationship<br />
                            <small class="text-muted">@r.Email &middot; @r.Phone</small>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Cover Letter</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                    </div>
                    <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

